import type {Point,HandleOffset} from '@/components/nyc-tron/ui/components/forge/vector/vector-types';
export interface MotionPathSnapping {readonly grid:number;readonly tolerance:number;readonly targets:readonly Point[];readonly tangentAngleDegrees:number}
export function validateMotionPathSnapping(s:MotionPathSnapping):void {if(![s.grid,s.tolerance,s.tangentAngleDegrees].every(Number.isFinite)||s.grid<0||s.grid>1e9||s.tolerance<0||s.tolerance>1e9||s.tangentAngleDegrees<0||s.tangentAngleDegrees>180||s.targets.length>10000||s.targets.some(p=>![p.x,p.y].every(Number.isFinite)))throw new RangeError('Invalid motion path snapping');}
/** Target points win equal-distance ties with the grid; points outside tolerance remain untouched. */
export function snapMotionPoint(point:Point,s:MotionPathSnapping):Point {validateMotionPathSnapping(s);if(![point.x,point.y].every(Number.isFinite))throw new RangeError('Invalid motion path point');let result=point,best=s.tolerance;for(const target of s.targets){const d=Math.hypot(target.x-point.x,target.y-point.y);if(d<=best&&(result===point||d<best)){best=d;result=target;}}if(s.grid>0){const grid={x:Math.round(point.x/s.grid)*s.grid,y:Math.round(point.y/s.grid)*s.grid},d=Math.hypot(grid.x-point.x,grid.y-point.y);if(d<=s.tolerance&&(result===point||d<best))result=grid;}return result;}
/** Snap tangent direction while retaining length. A zero increment leaves it unchanged. */
export function snapMotionTangent(offset:HandleOffset,degrees:number):HandleOffset {if(!offset.every(Number.isFinite)||offset.length!==2||!Number.isFinite(degrees)||degrees<0||degrees>180)throw new RangeError('Invalid motion path tangent');if(degrees===0)return offset;const length=Math.hypot(...offset),step=degrees*Math.PI/180,angle=Math.round(Math.atan2(offset[1],offset[0])/step)*step;return [Math.cos(angle)*length,Math.sin(angle)*length];}
